  }

  ## Check NUMS input
  nums &lt;- toupper(nums)
  if (length(nums) == 1 & nums == ("PWGTP")){
    #At least 1 numeric variable other than PWGTP required.
    stop("Invalid NUMS input. Must specify one more numeric variable in addition to PWGTP.")

  } else if (any(!nums %in% all_vars)){
    #Only variables on the approved list are accepted.
    #Note: any(not-in) == TRUE when any elements of nums are NOT in the elements of all_vars
    stop("Invalid NUMS input. At least one requested variable is not on the approved list.")

  } else if (any(!nums %in% c("AGEP", "GASP", "GRPIP", "JWAP", "JWDP", "JWMNP", "PWGTP"))) {
    #Only ~numeric~ variables on the approved list are accepted. Ask user to fix.
    stop("Invalid NUMS input. At least one requested variable is non-numeric.")

  } else {

    #Fix "ST" vs. "STATE" if entered wrong.
    if(yearc %in% c("2021", "2022") & nums %in% c("STATE")) {
      nums[which(nums == "STATE")] &lt;- "ST"

    } else if(yearc %in% c("2023", "2024") & nums %in% c("ST")) {
      nums[which(nums == "ST")] &lt;- "STATE"
    }

